const bridgeOutput = $input.first().json;
const raw = (bridgeOutput.output || '').trim();

// Parse disk usage percentage from df -h output
const dfMatch = raw.match(/(\d+)%/);
const diskPct = dfMatch ? parseInt(dfMatch[1], 10) : -1;

// Determine threshold level
let level = 'normal';
let emoji = '✅';
if (diskPct >= 90) { level = 'critical'; emoji = '\u{1F6A8}'; }
else if (diskPct >= 80) { level = 'alert'; emoji = '⚠️'; }
else if (diskPct >= 70) { level = 'warning'; emoji = '📊'; }

const shouldAlert = diskPct >= 70;

const ts = new Date().toISOString();

let actions = '';
if (diskPct >= 80) {
  actions = '\n\nAccoes sugeridas:\n- docker image prune -f\n- docker volume prune -f\n- Verificar modelos Ollama (du -sh ~/.ollama/models)\n- Limpar logs antigos n8n';
}
if (diskPct >= 90) {
  actions += '\n\n\u{1F6A8} CRITICO: Disco quase cheio! Risco de Docker/Ollama/Bridge pararem.';
}

const alertText = `${emoji} Disk Space Monitor — Mac Mini SSD\n\nUso: ${diskPct}% (nivel: ${level})\nTimestamp: ${ts}\n\nDetalhes:\n${raw}${actions}`;

return [{ json: {
  diskPct,
  level,
  shouldAlert,
  alertText,
  rawOutput: raw,
  timestamp: ts
}}];

